import type {
  NeighborRow, OverviewGroupRow, SourceFileRow, SourceIndexLevel, SourceSiteRow, SourceSymbolRow, SystemNodeKind, SystemOverviewPayload,
} from "./api";

// Renderer policy: a chosen bound, not a benchmark claim. Svelte Flow for small projections, Sigma above them, aggregation above Sigma's cap.
export const FLOW_MAX_NODES = 200;
export const FLOW_MAX_EDGES = 500;
export const SIGMA_MAX_NODES = 5000;
export const SIGMA_MAX_EDGES = 20000;
/** A system diagram generated by the Architect never exceeds these (backend-enforced); they only decide default grouping. */
export const SYSTEM_DEFAULT_GROUPS = 8;
export const NODE_W = 240;
export const NODE_H = 92;
export const COLUMN_W = 330;
export const ROW_H = 118;

export type Renderer = "flow" | "sigma";
export type GraphMode = "system" | "source";
export type Role = "input" | "app" | "output";
export type EvidenceState = "declared" | "inferred" | "unknown" | "analysis" | "parsed" | "partial" | "failed" | "unsupported" | "skipped" | "none";

export interface ModelNode {
  id: string;
  kind: string;
  label: string;
  subtitle: string;
  description: string;
  parentId: string | null;
  /** Structural container synthesized from paths (directory, file). Never an edge endpoint and not counted as an indexed node. */
  synthetic: boolean;
  evidence: EvidenceState;
  role: Role | null;
  evidenceIds: string[];
  /** Number of underlying indexed members (a strongly connected group has more than one). */
  memberCount: number;
  cyclic: boolean;
  selfLoops: number;
  selfLoopIds: string[];
  /** Members of a multi-member cycle known by id but whose internal edges load on demand. */
  lazyMembers: string[];
  /** Repository-relative path, when the node is a file or inside one. */
  path: string | null;
  /** Identity for index queries (file id or symbol id), when the node is an indexed fact. */
  ref: string | null;
}

export interface ModelEdge {
  id: string;
  source: string;
  target: string;
  relation: string;
  /** Source index: resolution. Architect system diagram: certainty. */
  grade: string;
  derived: boolean;
  label: string;
  /** Underlying source edges represented by this record (>= evidenceIds.length when the sample is truncated). */
  count: number;
  evidenceIds: string[];
  truncated: boolean;
}

export interface GraphModel { nodes: ModelNode[]; edges: ModelEdge[] }

export const compareText = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

export function node(partial: Partial<ModelNode> & Pick<ModelNode, "id" | "label">): ModelNode {
  return {
    kind: "node", subtitle: "", description: "", parentId: null, synthetic: false, evidence: "none", role: null, evidenceIds: [], memberCount: 1,
    cyclic: false, selfLoops: 0, selfLoopIds: [], lazyMembers: [], path: null, ref: null, ...partial,
  };
}

// ---- index ----------------------------------------------------------------------------------------------------

export interface GraphIndex {
  nodes: Map<string, ModelNode>;
  edges: ModelEdge[];
  children: Map<string, string[]>;
  parent: Map<string, string | null>;
  roots: string[];
  /** Nodes that are themselves an endpoint of at least one edge. */
  endpoints: Set<string>;
  /** Indexed members a node counts for by itself (not through its children): 0 for containers, the group size for a cycle/directory aggregate. */
  own: Map<string, number>;
  /** Sum of `own` over the node's subtree: the indexed facts (files/functions) a collapsed card represents. A cycle counts all its members, a directory aggregate its direct files plus those of every subdirectory. */
  members: Map<string, number>;
  /** Total indexed members of the model (what a readout calls "files"/"functions"). */
  totalNodes: number;
  /** Non-synthetic model nodes: a cycle group or a directory aggregate counts once however many members it holds. */
  totalGroups: number;
  totalEdges: number;
  /** Edges whose endpoint is not in the model (kept out of every projection and reported). */
  dangling: ModelEdge[];
  duplicates: number;
}

/** Validated lookup tables over a model: first duplicate wins, parent cycles are cut, dangling edges are set aside and counted. */
export function buildIndex(model: GraphModel): GraphIndex {
  const nodes = new Map<string, ModelNode>();
  let duplicates = 0;
  for (const item of model.nodes) {
    if (nodes.has(item.id)) { duplicates++; continue; }
    nodes.set(item.id, item);
  }
  const parent = new Map<string, string | null>();
  for (const [id, item] of nodes) parent.set(id, item.parentId !== null && item.parentId !== id && nodes.has(item.parentId) ? item.parentId : null);
  // A parent cycle is cut at the first node that closes it.
  for (const id of [...nodes.keys()].sort(compareText)) {
    const seen = new Set<string>([id]);
    let cursor = parent.get(id) ?? null;
    while (cursor !== null) {
      if (seen.has(cursor)) { parent.set(id, null); break; }
      seen.add(cursor);
      cursor = parent.get(cursor) ?? null;
    }
  }
  const children = new Map<string, string[]>();
  const roots: string[] = [];
  for (const id of nodes.keys()) {
    const owner = parent.get(id) ?? null;
    if (owner === null) roots.push(id);
    else { const list = children.get(owner); if (list) list.push(id); else children.set(owner, [id]); }
  }
  const byLabel = (a: string, b: string): number => compareText(nodes.get(a)!.label, nodes.get(b)!.label) || compareText(a, b);
  roots.sort(byLabel);
  for (const list of children.values()) list.sort(byLabel);
  const edges: ModelEdge[] = [];
  const dangling: ModelEdge[] = [];
  const endpoints = new Set<string>();
  for (const edge of model.edges) {
    if (!nodes.has(edge.source) || !nodes.has(edge.target)) { dangling.push(edge); continue; }
    edges.push(edge);
    endpoints.add(edge.source);
    endpoints.add(edge.target);
  }
  // Subtree sums in one iterative post-order (deep hierarchies cannot overflow the stack).
  const sums = (weight: (item: ModelNode) => number): Map<string, number> => {
    const totals = new Map<string, number>();
    for (const start of nodes.keys()) {
      if (totals.has(start)) continue;
      const stack: { id: string; next: number; total: number }[] = [{ id: start, next: 0, total: weight(nodes.get(start)!) }];
      while (stack.length) {
        const top = stack[stack.length - 1];
        const kids = children.get(top.id) ?? [];
        if (top.next < kids.length) {
          const kid = kids[top.next++];
          const done = totals.get(kid);
          if (done !== undefined) top.total += done;
          else stack.push({ id: kid, next: 0, total: weight(nodes.get(kid)!) });
        } else {
          totals.set(top.id, top.total);
          stack.pop();
          if (stack.length) stack[stack.length - 1].total += top.total;
        }
      }
    }
    return totals;
  };
  // A cycle group stands for all its members and a directory aggregate for its direct files; once a cycle's members are loaded as children they replace it.
  const own = new Map<string, number>();
  for (const [id, item] of nodes) own.set(id, item.synthetic ? 0 : item.lazyMembers.length > 0 ? Math.max(0, item.memberCount - (children.get(id)?.length ?? 0)) : item.memberCount);
  const members = sums(item => own.get(item.id) ?? 0);
  let totalNodes = 0, totalGroups = 0;
  for (const [id, item] of nodes) { totalNodes += own.get(id) ?? 0; if (!item.synthetic) totalGroups++; }
  return { nodes, edges, children, parent, roots, endpoints, own, members, totalNodes, totalGroups, totalEdges: edges.length, dangling, duplicates };
}

/** A container is a node with children, or a lazily loadable cycle. */
export const expandable = (index: GraphIndex, id: string): boolean => (index.children.get(id)?.length ?? 0) > 0 || (index.nodes.get(id)?.lazyMembers.length ?? 0) > 0;

// ---- strongly connected components ------------------------------------------------------------------------------

/** Iterative Tarjan over dense indexes. Components are returned sinks first; neighbour order is the given order. */
export function stronglyConnected(adjacency: readonly (readonly number[])[]): number[][] {
  const n = adjacency.length;
  const order = new Int32Array(n).fill(-1), low = new Int32Array(n), on = new Uint8Array(n);
  const stack: number[] = [];
  const components: number[][] = [];
  let counter = 0;
  for (let root = 0; root < n; root++) {
    if (order[root] !== -1) continue;
    const frames: { v: number; i: number }[] = [{ v: root, i: 0 }];
    order[root] = low[root] = counter++;
    stack.push(root);
    on[root] = 1;
    while (frames.length) {
      const frame = frames[frames.length - 1];
      const next = adjacency[frame.v];
      if (frame.i < next.length) {
        const w = next[frame.i++];
        if (order[w] === -1) {
          order[w] = low[w] = counter++;
          stack.push(w);
          on[w] = 1;
          frames.push({ v: w, i: 0 });
        } else if (on[w]) low[frame.v] = Math.min(low[frame.v], order[w]);
      } else {
        if (low[frame.v] === order[frame.v]) {
          const component: number[] = [];
          for (;;) {
            const w = stack.pop()!;
            on[w] = 0;
            component.push(w);
            if (w === frame.v) break;
          }
          components.push(component);
        }
        frames.pop();
        if (frames.length) {
          const parent = frames[frames.length - 1].v;
          low[parent] = Math.min(low[parent], low[frame.v]);
        }
      }
    }
  }
  return components;
}

// ---- layered layout ---------------------------------------------------------------------------------------------

export interface LayoutResult {
  column: Map<string, number>;
  row: Map<string, number>;
  /** Strongly connected component number per node; nodes of one component share a column. */
  component: Map<string, number>;
  componentSize: Map<number, number>;
  x: Map<string, number>;
  y: Map<string, number>;
  columns: number;
}

const BARYCENTER_NODE_LIMIT = 2000;
const bandOf = (role: Role | null): 0 | 1 | 2 => role === "input" ? 0 : role === "output" ? 2 : 1;

/**
 * Condenses strongly connected components, layers the acyclic result by longest path and orders each layer by stable id with a few
 * barycentre sweeps. With roles the columns run input -> application -> output regardless of edge direction. Response edges
 * (`responds`) never decide layers or components: a response is not a new caller.
 */
export function layoutLayers(nodes: readonly { id: string; role: Role | null }[], edges: readonly { source: string; target: string; relation: string }[], useRoles: boolean): LayoutResult {
  const ids = nodes.map(item => item.id).sort(compareText);
  const position = new Map(ids.map((id, i) => [id, i]));
  const roleOf = new Map(nodes.map(item => [item.id, item.role]));
  const adjacency: number[][] = ids.map(() => []);
  const neighbours: number[][] = ids.map(() => []);
  const seenPair = new Set<string>();
  for (const edge of edges) {
    const a = position.get(edge.source), b = position.get(edge.target);
    if (a === undefined || b === undefined || a === b) continue;
    neighbours[a].push(b);
    neighbours[b].push(a);
    if (edge.relation === "responds") continue;
    const key = `${a}:${b}`;
    if (seenPair.has(key)) continue;
    seenPair.add(key);
    adjacency[a].push(b);
  }
  for (const list of adjacency) list.sort((x, y) => x - y);
  const components = stronglyConnected(adjacency);
  const componentOf = new Int32Array(ids.length);
  // Number components by their smallest member id so numbering is independent of traversal order.
  const ordered = components.map(members => members.sort((a, b) => a - b)).sort((a, b) => a[0] - b[0]);
  ordered.forEach((members, c) => { for (const m of members) componentOf[m] = c; });
  const band = ordered.map(members => useRoles ? Math.min(...members.map(m => bandOf(roleOf.get(ids[m]) ?? null))) as 0 | 1 | 2 : 1);
  const successors: Set<number>[] = ordered.map(() => new Set<number>());
  const indegree = new Int32Array(ordered.length);
  for (let a = 0; a < ids.length; a++) {
    for (const b of adjacency[a]) {
      const from = componentOf[a], to = componentOf[b];
      if (from === to || successors[from].has(to)) continue;
      successors[from].add(to);
      indegree[to]++;
    }
  }
  const layer = new Int32Array(ordered.length);
  const ready: number[] = [];
  for (let c = 0; c < ordered.length; c++) if (indegree[c] === 0) ready.push(c);
  for (let head = 0; head < ready.length; head++) {
    const c = ready[head];
    for (const next of successors[c]) {
      if (band[next] === band[c]) layer[next] = Math.max(layer[next], layer[c] + 1);
      if (--indegree[next] === 0) ready.push(next);
    }
  }
  const depth = [0, 0, 0], used = [false, false, false];
  for (let c = 0; c < ordered.length; c++) { used[band[c]] = true; depth[band[c]] = Math.max(depth[band[c]], layer[c] + 1); }
  const base = [0, 0, 0];
  base[1] = used[0] ? depth[0] : 0;
  base[2] = base[1] + (used[1] ? depth[1] : 0);
  const columnOf = new Int32Array(ids.length);
  let columns = 0;
  for (let i = 0; i < ids.length; i++) {
    const c = componentOf[i];
    columnOf[i] = base[band[c]] + layer[c];
    columns = Math.max(columns, columnOf[i] + 1);
  }
  const perColumn: number[][] = Array.from({ length: columns }, () => []);
  for (let i = 0; i < ids.length; i++) perColumn[columnOf[i]].push(i);
  const rank = new Float64Array(ids.length);
  const place = (list: number[]): void => { list.forEach((m, r) => { rank[m] = list.length > 1 ? r / (list.length - 1) : 0.5; }); };
  for (const list of perColumn) { list.sort((a, b) => componentOf[a] - componentOf[b] || a - b); place(list); }
  if (ids.length <= BARYCENTER_NODE_LIMIT) {
    for (let sweep = 0; sweep < 4; sweep++) {
      const down = sweep % 2 === 0;
      const sequence = down ? [...perColumn.keys()] : [...perColumn.keys()].reverse();
      for (const c of sequence) {
        const list = perColumn[c];
        const unit = new Map<number, { sum: number; count: number }>();
        for (const m of list) {
          const entry = unit.get(componentOf[m]) ?? { sum: 0, count: 0 };
          for (const other of neighbours[m]) {
            if (down ? columnOf[other] < c : columnOf[other] > c) { entry.sum += rank[other]; entry.count++; }
          }
          unit.set(componentOf[m], entry);
        }
        const weight = (m: number): number => { const entry = unit.get(componentOf[m])!; return entry.count ? entry.sum / entry.count : rank[m]; };
        list.sort((a, b) => weight(a) - weight(b) || componentOf[a] - componentOf[b] || a - b);
        place(list);
      }
    }
  }
  const result: LayoutResult = { column: new Map(), row: new Map(), component: new Map(), componentSize: new Map(), x: new Map(), y: new Map(), columns };
  ordered.forEach((members, c) => result.componentSize.set(c, members.length));
  for (const list of perColumn) {
    list.forEach((m, r) => {
      const id = ids[m];
      result.column.set(id, columnOf[m]);
      result.row.set(id, r);
      result.component.set(id, componentOf[m]);
      result.x.set(id, columnOf[m] * COLUMN_W);
      result.y.set(id, (r - (list.length - 1) / 2) * ROW_H);
    });
  }
  return result;
}

// ---- projection -----------------------------------------------------------------------------------------------

export interface ProjectionLimits { flowNodes: number; flowEdges: number; sigmaNodes: number; sigmaEdges: number }
export const DEFAULT_LIMITS: ProjectionLimits = { flowNodes: FLOW_MAX_NODES, flowEdges: FLOW_MAX_EDGES, sigmaNodes: SIGMA_MAX_NODES, sigmaEdges: SIGMA_MAX_EDGES };

export interface ProjectionOptions {
  mode: GraphMode;
  /** Containers the user opened. Null: the automatic default cut. */
  expanded: ReadonlySet<string> | null;
  /** Edge filters (null = everything). They only hide arrows; node membership is unaffected. */
  relations?: ReadonlySet<string> | null;
  grades?: ReadonlySet<string> | null;
  derived?: boolean;
  /** Zero-based window when even the fully aggregated projection exceeds the renderer cap. */
  page?: number;
  limits?: ProjectionLimits;
}

export interface ViewNode {
  id: string;
  kind: string;
  label: string;
  subtitle: string;
  description: string;
  evidence: EvidenceState;
  role: Role | null;
  /** Indexed nodes represented (descendants of a collapsed container, or cycle members). */
  memberCount: number;
  /** True when this card stands for hidden children. */
  collapsed: boolean;
  /** True for an opened container that stays visible because it has relationships of its own. */
  open: boolean;
  expandable: boolean;
  cyclic: boolean;
  selfLoops: number;
  selfLoopIds: string[];
  /** Edges entirely inside this collapsed card. */
  internal: number;
  /** Labels of the containing groups, outermost first. */
  within: string[];
  path: string | null;
  ref: string | null;
  evidenceIds: string[];
  column: number;
  row: number;
  component: number;
  x: number;
  y: number;
  degree: number;
}

export interface ViewEdge {
  id: string;
  source: string;
  target: string;
  relation: string;
  grade: string;
  derived: boolean;
  label: string;
  /** Underlying source records behind this arrow. */
  count: number;
  /** Ids of the model edges aggregated here (always complete), and their evidence records. */
  edgeIds: string[];
  evidenceIds: string[];
  truncated: boolean;
  /** Both ends belong to one strongly connected component. */
  cycle: boolean;
  /** A response never counts as a new caller. */
  response: boolean;
  /** Runs against the column order (feedback). */
  back: boolean;
}

export interface Projection {
  nodes: ViewNode[];
  edges: ViewEdge[];
  renderer: Renderer;
  /** Counts of the whole model, so displayed/total always reconcile. `nodes` counts underlying indexed members (a cycle group counts all its files, a directory aggregate its direct and nested files); `groups` counts the graph nodes those members are drawn as. */
  total: { nodes: number; groups: number; edges: number };
  displayed: { nodes: number; edges: number };
  /** Edges not drawn as arrows: inside a collapsed card, recursion shown on a card, removed by filters, or with an unknown end. */
  accounted: { internal: number; recursion: number; filtered: number; dangling: number; openContainers: number };
  aggregated: boolean;
  /** Why the view is aggregated or paged, in plain words. */
  reason: string | null;
  paged: { page: number; pages: number; pageSize: number } | null;
  expanded: string[];
  columns: number;
}

interface ViewEdgeDraft { source: string; target: string; relation: string; grade: string; derived: boolean; label: string; edgeIds: string[]; evidenceIds: Set<string>; count: number; truncated: boolean }
interface Aggregate {
  shown: Set<string>;
  edges: Map<string, ViewEdgeDraft>;
  /** Edges (by count) entirely inside a collapsed card. */
  internal: Map<string, number>;
  /** Recursion per card: model edges from a node to itself, plus the self-loops the index counted on indexed nodes. */
  recursion: Map<string, { count: number; ids: string[] }>;
  /** Members hidden inside collapsed cards are counted per card by `members`; this is the model-wide total of recursion. */
  recursionTotal: number;
  filtered: number;
  internalTotal: number;
}

/** An opened container stays a card when it has relationships of its own, or when it is a directory aggregate that holds files directly (those would otherwise vanish from the view). */
function staysVisibleOpen(index: GraphIndex, id: string): boolean {
  const item = index.nodes.get(id)!;
  return index.endpoints.has(id) || (item.kind === "directory" && !item.synthetic && (index.own.get(id) ?? 0) > 0);
}

function shownSet(index: GraphIndex, expanded: ReadonlySet<string>): Set<string> {
  const shown = new Set<string>();
  const stack = [...index.roots];
  while (stack.length) {
    const id = stack.pop()!;
    const kids = index.children.get(id);
    if (kids?.length && expanded.has(id)) {
      // An opened container stays visible only for relationships of its own, or for the files an aggregate directory holds directly.
      if (staysVisibleOpen(index, id)) shown.add(id);
      for (const kid of kids) stack.push(kid);
    } else shown.add(id);
  }
  return shown;
}

function aggregate(index: GraphIndex, expanded: ReadonlySet<string>, options: ProjectionOptions): Aggregate {
  const shown = shownSet(index, expanded);
  const representative = new Map<string, string>();
  const repOf = (id: string): string => {
    const known = representative.get(id);
    if (known !== undefined) return known;
    // The first collapsed container on the way down from the root represents every node below it.
    const chain: string[] = [];
    for (let cursor: string | null = id; cursor !== null; cursor = index.parent.get(cursor) ?? null) chain.push(cursor);
    let rep = id;
    for (let i = chain.length - 1; i > 0; i--) if (!expanded.has(chain[i])) { rep = chain[i]; break; }
    representative.set(id, rep);
    return rep;
  };
  const edges = new Map<string, ViewEdgeDraft>();
  const internal = new Map<string, number>();
  const recursion = new Map<string, { count: number; ids: string[] }>();
  const addRecursion = (card: string, count: number, id: string | null): void => {
    const entry = recursion.get(card) ?? { count: 0, ids: [] };
    entry.count += count;
    if (id !== null) entry.ids.push(id);
    recursion.set(card, entry);
  };
  let filtered = 0, internalTotal = 0, recursionTotal = 0;
  // Self-loops counted by the index on a node itself (recursion) are not model edges but belong to that node's card.
  for (const item of index.nodes.values()) {
    if (item.selfLoops > 0 && !item.synthetic) { addRecursion(repOf(item.id), item.selfLoops, null); recursionTotal += item.selfLoops; }
  }
  for (const edge of index.edges) {
    if ((options.relations && !options.relations.has(edge.relation)) || (options.grades && !options.grades.has(edge.grade)) || (options.derived === false && edge.derived)) { filtered += edge.count; continue; }
    const from = repOf(edge.source), to = repOf(edge.target);
    if (edge.source === edge.target) { addRecursion(from, edge.count, edge.id); recursionTotal += edge.count; continue; }
    if (from === to) { internal.set(from, (internal.get(from) ?? 0) + edge.count); internalTotal += edge.count; continue; }
    const key = `${from}>${to}|${edge.relation}|${edge.grade}|${edge.derived ? 1 : 0}`;
    const draft = edges.get(key);
    if (draft) {
      draft.edgeIds.push(edge.id);
      for (const id of edge.evidenceIds) draft.evidenceIds.add(id);
      draft.count += edge.count;
      draft.truncated ||= edge.truncated;
      if (draft.label !== edge.label) draft.label = "";
    } else edges.set(key, { source: from, target: to, relation: edge.relation, grade: edge.grade, derived: edge.derived, label: edge.label, edgeIds: [edge.id], evidenceIds: new Set(edge.evidenceIds), count: edge.count, truncated: edge.truncated });
  }
  return { shown, edges, internal, recursion, recursionTotal, filtered, internalTotal };
}

/** Initial cut: open containers breadth-first while the visible node count fits the Flow bound; the edge bound is applied by `fitExpanded`. */
export function defaultExpanded(index: GraphIndex, mode: GraphMode, limits: ProjectionLimits = DEFAULT_LIMITS): Set<string> {
  const expanded = new Set<string>();
  if (mode === "system") {
    // One application-flow box, or a few meaningful groups.
    for (const id of index.roots) {
      const kids = index.children.get(id) ?? [];
      if (index.nodes.get(id)!.kind === "application" && kids.length > 0 && kids.length <= SYSTEM_DEFAULT_GROUPS) expanded.add(id);
    }
    return expanded;
  }
  let count = index.roots.length;
  let level = [...index.roots];
  while (level.length) {
    const next: string[] = [];
    for (const id of level) {
      const kids = index.children.get(id);
      if (!kids?.length) continue;
      const after = count - (staysVisibleOpen(index, id) ? 0 : 1) + kids.length;
      if (after > limits.flowNodes) continue;
      expanded.add(id);
      count = after;
      next.push(...kids);
    }
    level = next;
  }
  return expanded;
}

/**
 * Collapses opened containers, deepest level first, until the projection fits `nodes`/`edges`. Within the level that makes it fit,
 * the fewest containers (largest first) are collapsed, found by bisection.
 */
function fitExpanded(index: GraphIndex, expanded: ReadonlySet<string>, options: ProjectionOptions, nodes: number, edges: number): { expanded: Set<string>; collapsed: number } {
  const open = new Set([...expanded].filter(id => (index.children.get(id)?.length ?? 0) > 0));
  const fits = (set: ReadonlySet<string>): boolean => { const measured = aggregate(index, set, options); return measured.shown.size <= nodes && measured.edges.size <= edges; };
  if (fits(open)) return { expanded: open, collapsed: 0 };
  const byDepth = new Map<number, string[]>();
  for (const id of open) {
    let depth = 0;
    for (let cursor = index.parent.get(id) ?? null; cursor !== null; cursor = index.parent.get(cursor) ?? null) depth++;
    const list = byDepth.get(depth);
    if (list) list.push(id); else byDepth.set(depth, [id]);
  }
  let collapsed = 0;
  for (const depth of [...byDepth.keys()].sort((a, b) => b - a)) {
    const level = byDepth.get(depth)!.sort((a, b) => (index.members.get(b) ?? 0) - (index.members.get(a) ?? 0) || compareText(a, b));
    const without = (count: number): Set<string> => { const trial = new Set(open); for (let i = 0; i < count; i++) trial.delete(level[i]); return trial; };
    if (!fits(without(level.length))) {
      for (const id of level) open.delete(id);
      collapsed += level.length;
      continue;
    }
    let low = 1, high = level.length;
    while (low < high) {
      const middle = (low + high) >> 1;
      if (fits(without(middle))) high = middle; else low = middle + 1;
    }
    for (let i = 0; i < high; i++) open.delete(level[i]);
    return { expanded: open, collapsed: collapsed + high };
  }
  return { expanded: open, collapsed };
}

export function chooseRenderer(mode: GraphMode, nodeCount: number, edgeCount: number, limits: ProjectionLimits = DEFAULT_LIMITS): Renderer {
  if (mode === "system") return "flow";
  return nodeCount <= limits.flowNodes && edgeCount <= limits.flowEdges ? "flow" : "sigma";
}

/** Prefer a grouped view that fits Flow; when grouping leaves fewer than two cards (one flat directory) show the whole level in Sigma instead. */
function automaticCut(index: GraphIndex, options: ProjectionOptions, limits: ProjectionLimits): ReadonlySet<string> {
  const flow = fitExpanded(index, defaultExpanded(index, options.mode, limits), options, limits.flowNodes, limits.flowEdges).expanded;
  if (options.mode === "system" || shownSet(index, flow).size >= 2) return flow;
  return defaultExpanded(index, options.mode, { ...limits, flowNodes: limits.sigmaNodes });
}

/**
 * The induced subgraph both renderers draw. Containment never becomes an arrow: containers are collapsed into one card or replaced by
 * their children. Every arrow keeps the ids of the model edges and evidence records behind it, and every model edge is accounted for.
 */
export function projectGraph(index: GraphIndex, options: ProjectionOptions): Projection {
  const limits = options.limits ?? DEFAULT_LIMITS;
  const system = options.mode === "system";
  const maxNodes = system ? limits.flowNodes : limits.sigmaNodes;
  const maxEdges = system ? limits.flowEdges : limits.sigmaEdges;
  const automatic = options.expanded === null;
  const wanted = options.expanded ?? automaticCut(index, options, limits);
  const fitted = fitExpanded(index, wanted, options, maxNodes, maxEdges);
  const expanded = fitted.expanded;
  const measured = aggregate(index, expanded, options);
  const ids = [...measured.shown];
  const layout = layoutLayers(ids.map(id => ({ id, role: index.nodes.get(id)!.role })), [...measured.edges.values()], system);
  const degree = new Map<string, number>();
  for (const edge of measured.edges.values()) {
    degree.set(edge.source, (degree.get(edge.source) ?? 0) + 1);
    degree.set(edge.target, (degree.get(edge.target) ?? 0) + 1);
  }
  ids.sort((a, b) => (layout.column.get(a)! - layout.column.get(b)!) || (layout.row.get(a)! - layout.row.get(b)!) || compareText(a, b));
  // Still too large with everything collapsed: window the projection instead of dropping the rest silently.
  const pageSize = maxNodes;
  const pages = Math.max(1, Math.ceil(ids.length / pageSize));
  const page = Math.min(Math.max(0, options.page ?? 0), pages - 1);
  const windowIds = pages > 1 ? ids.slice(page * pageSize, (page + 1) * pageSize) : ids;
  const windowSet = new Set(windowIds);
  let indexedDisplayed = 0;
  const nodes: ViewNode[] = windowIds.map(id => {
    const item = index.nodes.get(id)!;
    const kids = index.children.get(id);
    const isOpen = expanded.has(id) && !!kids?.length;
    const collapsed = (kids?.length ?? 0) > 0 && !isOpen;
    const within: string[] = [];
    for (let cursor = index.parent.get(id) ?? null; cursor !== null; cursor = index.parent.get(cursor) ?? null) within.unshift(index.nodes.get(cursor)!.label);
    const loops = measured.recursion.get(id);
    indexedDisplayed += collapsed ? index.members.get(id) ?? 0 : index.own.get(id) ?? 0;
    return {
      id, kind: item.kind, label: item.label, subtitle: item.subtitle, description: item.description, evidence: item.evidence, role: item.role,
      memberCount: collapsed ? index.members.get(id) ?? 0 : item.memberCount, collapsed, open: isOpen, expandable: expandable(index, id),
      cyclic: item.cyclic, selfLoops: loops?.count ?? 0, selfLoopIds: loops?.ids ?? [],
      internal: measured.internal.get(id) ?? 0, within, path: item.path, ref: item.ref, evidenceIds: item.evidenceIds,
      column: layout.column.get(id)!, row: layout.row.get(id)!, component: layout.component.get(id)!, x: layout.x.get(id)!, y: layout.y.get(id)!, degree: degree.get(id) ?? 0,
    };
  });
  const edges: ViewEdge[] = [];
  for (const [key, draft] of measured.edges) {
    if (!windowSet.has(draft.source) || !windowSet.has(draft.target)) continue;
    const cycle = layout.component.get(draft.source) === layout.component.get(draft.target);
    const response = draft.relation === "responds";
    edges.push({
      id: key, source: draft.source, target: draft.target, relation: draft.relation, grade: draft.grade, derived: draft.derived, label: draft.label,
      count: draft.count, edgeIds: draft.edgeIds, evidenceIds: [...draft.evidenceIds], truncated: draft.truncated, cycle, response,
      back: !response && !cycle && layout.column.get(draft.target)! <= layout.column.get(draft.source)!,
    });
  }
  edges.sort((a, b) => compareText(a.id, b.id));
  // Opened non-synthetic containers without relationships of their own are not cards; they stay counted.
  let openHidden = 0;
  for (const id of expanded) {
    const item = index.nodes.get(id);
    if (item && !item.synthetic && (index.children.get(id)?.length ?? 0) > 0 && !measured.shown.has(id)) openHidden++;
  }
  const edgeTotal = index.edges.reduce((sum, edge) => sum + edge.count, 0);
  const reasons: string[] = [];
  if (fitted.collapsed > 0) reasons.push(`Groups were collapsed to keep the view within ${maxNodes.toLocaleString()} nodes and ${maxEdges.toLocaleString()} arrows.`);
  if (pages > 1) reasons.push(`Even fully grouped, the view has ${ids.length.toLocaleString()} nodes; showing window ${page + 1} of ${pages}.`);
  const oversize = nodes.filter(item => item.collapsed && item.memberCount > maxNodes);
  if (oversize.length) reasons.push(`${oversize.length === 1 ? `"${oversize[0].label}" holds` : `${oversize.length} groups hold`} more than ${maxNodes.toLocaleString()} nodes, which is more than the view can draw; use search to open an exact neighbourhood.`);
  const total = edgeTotal + selfIndexLoops(index) + danglingCount(index);
  return {
    nodes, edges, renderer: chooseRenderer(options.mode, nodes.length, edges.length, limits),
    total: { nodes: index.totalNodes, groups: index.totalGroups, edges: total },
    displayed: { nodes: indexedDisplayed, edges: edges.reduce((sum, item) => sum + item.count, 0) },
    accounted: { internal: measured.internalTotal, recursion: measured.recursionTotal, filtered: measured.filtered, dangling: danglingCount(index), openContainers: openHidden },
    aggregated: nodes.some(item => item.collapsed) || automatic && fitted.collapsed > 0, reason: reasons.length ? reasons.join(" ") : null,
    paged: pages > 1 ? { page, pages, pageSize } : null,
    expanded: [...expanded], columns: layout.columns,
  };
}

const danglingCount = (index: GraphIndex): number => index.dangling.reduce((sum, edge) => sum + edge.count, 0);
const selfIndexLoops = (index: GraphIndex): number => { let sum = 0; for (const item of index.nodes.values()) if (!item.synthetic) sum += item.selfLoops; return sum; };

/** Edge accounting: drawn + inside cards + recursion + filtered + dangling equals the model total, unless the view is windowed. */
export function edgeCountsReconcile(index: GraphIndex, projection: Projection): boolean {
  if (projection.paged) return true;
  const { internal, recursion, filtered, dangling } = projection.accounted;
  return projection.displayed.edges + internal + recursion + filtered + dangling === projection.total.edges
    && projection.total.edges === index.edges.reduce((sum, edge) => sum + edge.count, 0) + selfIndexLoops(index) + danglingCount(index);
}

// ---- model builders -------------------------------------------------------------------------------------------

const ROLE_BY_KIND: Partial<Record<SystemNodeKind, Role>> = {
  actor: "input", entrypoint: "input", application: "app", logicGroup: "app", database: "output", cache: "output", queue: "output", storage: "output",
};
const AMBIGUOUS: ReadonlySet<string> = new Set<SystemNodeKind>(["external", "service", "sidecar"]);

/**
 * The Architect's system diagram as a model. Nodes keep their evidence ids; arrows keep certainty and the static fact id as grade/evidence.
 * Ambiguous kinds (external/service/sidecar) become inputs when only they call the application, outputs when the application calls them.
 */
export function modelFromSystem(payload: SystemOverviewPayload): GraphModel {
  const kindOf = new Map(payload.nodes.map(item => [item.id, item.kind]));
  const inbound = new Set<string>(), outbound = new Set<string>();
  const insideApp = (id: string): boolean => { const kind = kindOf.get(id); return kind === "application" || kind === "logicGroup"; };
  for (const edge of payload.edges) {
    if (edge.relation === "responds") continue;
    if (insideApp(edge.targetId) && !insideApp(edge.sourceId)) inbound.add(edge.sourceId);
    if (insideApp(edge.sourceId) && !insideApp(edge.targetId)) outbound.add(edge.targetId);
  }
  const nodes = payload.nodes.map(item => {
    let role: Role | null = ROLE_BY_KIND[item.kind] ?? null;
    if (role === null && AMBIGUOUS.has(item.kind)) role = outbound.has(item.id) ? "output" : inbound.has(item.id) ? "input" : "output";
    return node({
      id: item.id, kind: item.kind, label: item.label, description: item.description, parentId: item.parentId, evidence: "analysis", role,
      evidenceIds: item.evidenceIds, subtitle: item.kind,
    });
  });
  const edges: ModelEdge[] = payload.edges.map(item => ({
    id: item.id, source: item.sourceId, target: item.targetId, relation: item.relation, grade: item.certainty, derived: false, label: item.label,
    count: 1, evidenceIds: item.staticFactId ? [...item.evidenceIds, item.staticFactId] : item.evidenceIds, truncated: false,
  }));
  return { nodes, edges };
}

/** Before any generated diagram exists: a single central application box and nothing invented around it. */
export function placeholderSystemModel(label: string): GraphModel {
  return { nodes: [node({ id: "application", kind: "application", label, subtitle: "application", description: "No generated system diagram yet.", role: "app" })], edges: [] };
}

const FILE_STATUS: Record<string, EvidenceState> = { parsed: "parsed", partial: "partial", failed: "failed", skipped: "skipped", unsupported: "unsupported" };

export const dirOf = (path: string): string => { const cut = path.lastIndexOf("/"); return cut < 0 ? "" : path.slice(0, cut); };
export const baseName = (path: string): string => path.slice(path.lastIndexOf("/") + 1);
export const dirId = (path: string): string => `dir:${path}`;
export const fileContainerId = (path: string): string => `file:${path}`;

export interface OverviewInput {
  level: SourceIndexLevel;
  /** Groups of the strongly-connected-component overview, all pages. */
  groups: readonly OverviewGroupRow[];
  files?: readonly SourceFileRow[];
  symbols?: readonly SourceSymbolRow[];
  /** Admitted directory paths (including empty ones). */
  directories?: readonly string[];
}

/** Longest shared directory of several paths. */
function commonDirectory(paths: readonly string[]): string {
  if (!paths.length) return "";
  let prefix = dirOf(paths[0]).split("/").filter(Boolean);
  for (const path of paths) {
    const parts = dirOf(path).split("/").filter(Boolean);
    let i = 0;
    while (i < prefix.length && i < parts.length && prefix[i] === parts[i]) i++;
    prefix = prefix.slice(0, i);
  }
  return prefix.join("/");
}

/**
 * The index's per-node strongly-connected overview as a model. Every group is a node (isolated files/functions included); every link
 * keeps its relation, resolution, derived flag, total count and the sampled underlying edge ids. Directories (and files, for functions)
 * are synthesized only as containers. Containment is never an edge.
 */
export function modelFromOverview(input: OverviewInput): GraphModel {
  const files = new Map((input.files ?? []).map(item => [item.id, item]));
  const symbols = new Map((input.symbols ?? []).map(item => [item.id, item]));
  const nodes: ModelNode[] = [];
  const nodeOfGroup = new Map<string, string>();
  const containers = new Map<string, ModelNode>();
  const ensureDir = (path: string): string => {
    const id = dirId(path);
    if (containers.has(id)) return id;
    const parent = path === "" ? null : ensureDir(dirOf(path));
    containers.set(id, node({ id, kind: "directory", label: path === "" ? "." : baseName(path), subtitle: path, parentId: parent, synthetic: true, path: path === "" ? null : path }));
    return id;
  };
  const ensureFile = (path: string): string => {
    const id = fileContainerId(path);
    if (containers.has(id)) return id;
    const parent = ensureDir(dirOf(path));
    containers.set(id, node({ id, kind: "file", label: baseName(path), subtitle: path, parentId: parent, synthetic: true, path }));
    return id;
  };
  ensureDir("");
  for (const directory of input.directories ?? []) ensureDir(directory);
  for (const group of input.groups) {
    const single = group.memberCount === 1 && group.members.length === 1;
    const memberId = group.members[0];
    let path: string | null = null;
    let parent: string;
    let kind = "cycle";
    let evidence: EvidenceState = "none";
    let subtitle = "";
    const id = single ? memberId : group.id;
    if (input.level === "files") {
      const row = single ? files.get(memberId) : undefined;
      path = single ? row?.path ?? group.label : null;
      if (single) { kind = "file"; evidence = row ? FILE_STATUS[row.status] ?? "none" : "none"; subtitle = row?.language ?? ""; }
      else {
        const known = group.members.map(member => files.get(member)?.path).filter((value): value is string => !!value);
        parent = ensureDir(commonDirectory(known));
        nodes.push(node({ id, kind, label: group.label, parentId: parent, cyclic: true, memberCount: group.memberCount, path: null, ref: group.id, evidence: "parsed", subtitle: `${group.memberCount} files in a cycle`, lazyMembers: group.membersTruncated ? [] : [...group.members] }));
        nodeOfGroup.set(group.id, id);
        continue;
      }
      parent = ensureDir(dirOf(path ?? group.label));
    } else {
      const row = single ? symbols.get(memberId) : undefined;
      if (single) {
        path = row?.path ?? null; kind = row?.kind ?? "function"; evidence = "parsed";
        subtitle = row ? `${row.path}:${row.span.lineStart}` : "";
        parent = path !== null ? ensureFile(path) : ensureDir("");
      } else {
        const known = group.members.map(member => symbols.get(member)?.path).filter((value): value is string => !!value);
        const common = commonDirectory(known);
        const sameFile = known.length > 0 && known.every(value => value === known[0]);
        parent = sameFile ? ensureFile(known[0]) : ensureDir(common);
        nodes.push(node({ id, kind, label: group.label, parentId: parent, cyclic: true, memberCount: group.memberCount, ref: group.id, evidence: "parsed", subtitle: `${group.memberCount} functions in a cycle`, lazyMembers: group.membersTruncated ? [] : [...group.members] }));
        nodeOfGroup.set(group.id, id);
        continue;
      }
    }
    nodes.push(node({
      id, kind, label: input.level === "files" ? baseName(group.label) : group.label, subtitle: input.level === "files" ? path ?? "" : subtitle,
      parentId: parent, evidence, path, ref: memberId, cyclic: group.cyclic, selfLoops: group.internalEdges, memberCount: 1,
    }));
    nodeOfGroup.set(group.id, id);
  }
  const edges: ModelEdge[] = [];
  for (const group of input.groups) {
    const from = nodeOfGroup.get(group.id);
    if (from === undefined) continue;
    for (const link of group.links) {
      const to = nodeOfGroup.get(link.targetGroupId) ?? link.targetGroupId;
      edges.push({
        id: `${group.id}>${link.targetGroupId}|${link.relation}|${link.resolution}|${link.derived ? 1 : 0}`, source: from, target: to, relation: link.relation,
        grade: link.resolution, derived: link.derived, label: link.relation, count: link.count, evidenceIds: link.edgeIds, truncated: link.edgeIdsTruncated || link.count > link.edgeIds.length,
      });
    }
  }
  return { nodes: [...containers.values(), ...nodes], edges };
}

/**
 * The directory-level overview (used when the per-node graph exceeds the Sigma bound): every directory is a node carrying its direct
 * file/function count; links are aggregated between directories with their relation/resolution, totals and sampled edge ids.
 */
export function modelFromDirectories(groups: readonly OverviewGroupRow[]): GraphModel {
  const nodes = groups.map(group => node({
    id: group.id, kind: "directory", label: group.label === "." ? "." : baseName(group.path ?? group.label), subtitle: group.path ?? group.label,
    parentId: group.parentId ?? null, memberCount: group.memberCount, evidence: "parsed", path: group.path ? group.path : null,
  }));
  const edges: ModelEdge[] = [];
  for (const group of groups) {
    for (const link of group.links) {
      edges.push({
        id: `${group.id}>${link.targetGroupId}|${link.relation}|${link.resolution}|${link.derived ? 1 : 0}`, source: group.id, target: link.targetGroupId, relation: link.relation,
        grade: link.resolution, derived: link.derived, label: link.relation, count: link.count, evidenceIds: link.edgeIds, truncated: link.edgeIdsTruncated || link.count > link.edgeIds.length,
      });
    }
  }
  return { nodes, edges };
}

export interface NeighborhoodInput {
  level: SourceIndexLevel;
  centerId: string;
  centerLabel: string;
  centerPath: string | null;
  rows: readonly NeighborRow[];
}

/** Exact neighbourhood of one node from neighbour rows: peers become nodes, edge rows keep their site evidence, missing endpoints stay sites. */
export function modelFromNeighbors(input: NeighborhoodInput): { model: GraphModel; sites: SourceSiteRow[] } {
  const nodes = new Map<string, ModelNode>();
  const edges: ModelEdge[] = [];
  const sites: SourceSiteRow[] = [];
  const kind = input.level === "files" ? "file" : "function";
  nodes.set(input.centerId, node({ id: input.centerId, kind, label: input.level === "files" ? baseName(input.centerLabel) : input.centerLabel, subtitle: input.centerPath ?? "", path: input.centerPath, ref: input.centerId, evidence: "parsed" }));
  const peer = (id: string, label: string | null): void => {
    if (nodes.has(id)) return;
    nodes.set(id, node({ id, kind, label: label ? (input.level === "files" ? baseName(label) : label) : id, subtitle: input.level === "files" ? label ?? "" : "", path: input.level === "files" ? label : null, ref: id, evidence: "parsed" }));
  };
  for (const row of input.rows) {
    if (row.kind === "edge") {
      peer(row.peerId, row.peerLabel);
      const outgoing = row.direction === "out";
      edges.push({
        id: row.edge.id, source: outgoing ? input.centerId : row.peerId, target: outgoing ? row.peerId : input.centerId, relation: row.edge.relation,
        grade: row.edge.resolution, derived: false, label: row.edge.relation, count: 1, evidenceIds: row.edge.evidenceIds, truncated: false,
      });
    } else if (row.kind === "aggregate" && row.peerId) {
      peer(row.peerId, row.peerLabel);
      const outgoing = row.direction === "out";
      edges.push({
        id: `agg:${row.direction}:${row.peerId}:${row.relation}:${row.resolution}`, source: outgoing ? input.centerId : row.peerId, target: outgoing ? row.peerId : input.centerId,
        relation: row.relation, grade: row.resolution, derived: true, label: row.relation, count: row.count, evidenceIds: row.edgeIds, truncated: row.edgeIdsTruncated || row.count > row.edgeIds.length,
      });
    } else if (row.kind === "site") sites.push(row.site);
  }
  return { model: { nodes: [...nodes.values()], edges }, sites };
}

/** Restricts a model to nodes accepted by `keep` (structural containers survive only while they still contain an accepted node). */
export function scopeModel(model: GraphModel, keep: (node: ModelNode) => boolean): GraphModel {
  const accepted = new Set(model.nodes.filter(item => !item.synthetic && keep(item)).map(item => item.id));
  const byId = new Map(model.nodes.map(item => [item.id, item]));
  const live = new Set(accepted);
  for (const id of accepted) {
    for (let cursor = byId.get(id)?.parentId ?? null; cursor !== null && !live.has(cursor); cursor = byId.get(cursor)?.parentId ?? null) live.add(cursor);
  }
  return { nodes: model.nodes.filter(item => live.has(item.id)), edges: model.edges.filter(edge => accepted.has(edge.source) && accepted.has(edge.target)) };
}

/** Case-insensitive label/description match for the System diagram search box. Empty text matches nothing. */
export function matchNodes(index: GraphIndex, text: string): string[] {
  const needle = text.trim().toLowerCase();
  if (!needle) return [];
  const hits: string[] = [];
  for (const item of index.nodes.values()) {
    if (!item.synthetic && (item.label.toLowerCase().includes(needle) || item.description.toLowerCase().includes(needle) || (item.path ?? "").toLowerCase().includes(needle))) hits.push(item.id);
  }
  return hits.sort(compareText);
}

/** Opens every ancestor of `id` so the node becomes a visible card (used when selecting a search hit). */
export function revealPath(index: GraphIndex, id: string, expanded: ReadonlySet<string> | null, mode: GraphMode): Set<string> {
  const open = new Set(expanded ?? defaultExpanded(index, mode));
  for (let cursor = index.parent.get(id) ?? null; cursor !== null; cursor = index.parent.get(cursor) ?? null) open.add(cursor);
  return open;
}

// ---- presentation helpers (plain text only) -------------------------------------------------------------------

export const RELATION_COLORS: Record<string, string> = {
  calls: "#4ea1ff", imports: "#8b9bb4", includes: "#8b9bb4", reexports: "#a371f7", references: "#61708a", renders: "#3fb950", macros: "#d29922", instantiates: "#d29922",
  requests: "#4ea1ff", responds: "#3fb950", publishes: "#d29922", subscribes: "#d29922", reads: "#2bb8b8", writes: "#f0883e", authorizes: "#ff69b4",
};
export const relationColor = (relation: string): string => RELATION_COLORS[relation] ?? "#8b9bb4";

/** Resolution/certainty a human can trust at a glance; only `resolvedStatic` and `declared` are statically proven. */
export function gradeText(grade: string): string {
  switch (grade) {
    case "resolvedStatic": return "Resolved statically";
    case "candidate": return "Candidate (not unique)";
    case "dynamic": return "Dynamic";
    case "external": return "External";
    case "unresolved": return "Unresolved";
    case "unsupported": return "Unsupported";
    case "declared": return "Declared by static fact";
    case "inferred": return "Inferred by the Architect";
    case "unknown": return "Unknown";
    default: return grade;
  }
}
export const gradeProven = (grade: string): boolean => grade === "resolvedStatic" || grade === "declared";
/** Arrow dash: proven solid, everything else dashed so an inference is never mistaken for a proven edge. */
export const edgeDashed = (edge: Pick<ViewEdge, "grade" | "response">): boolean => edge.response || !gradeProven(edge.grade);

/** Display-only clipping; the full text always stays in the model and is shown on selection. */
export function clipText(text: string, max: number): string {
  const chars = [...text];
  return chars.length <= max ? text : `${chars.slice(0, Math.max(1, max - 1)).join("")}…`;
}
